  #endpoint.yt-simple-endpoint.ytd-guide-entry-renderer,
  tp-yt-paper-item.ytd-compact-link-renderer,
  .yt-multi-page-menu-section-renderer,
  #container.ytd-searchbox,
  #header.ytd-app,
  .yt-spec-button-shape-next--mono.yt-spec-button-shape-next--tonal,
  #video-title,
  ytd-text-inline-expander,
  ytd-comments-entry-point-header-renderer[modern-metapanel],
  tp-yt-paper-listbox,
  .yt-spec-button-shape-next--call-to-action.yt-spec-button-shape-next--outline,
  [aria-selected="true"],
  .ytp-popup,
  #header.ytd-engagement-panel-title-header-renderer,
  #emojis.ytd-commentbox,
  .emoji-mart,
  .ytSearchboxComponentInputBox {
    transform-origin: bottom left;
    animation: Like 1000ms var(--standard-ease) forwards;
  }
  #links-holder .style-scope.ytd-c4-tabbed-header-renderer {
    box-shadow: inset 0px 0px 10px var(--clr_like);
    border-radius: 10px 0px 10px 0;
    transform-origin: bottom left;
    animation: Like 1000ms var(--standard-ease) forwards;
  }
  :root {
    --clr_like: #0099ff;
    --color-transition-duration: 1s;
    --standard-ease: cubic-bezier(0.4, 0, 0.2, 1);
  }
  #segmented-like-button button[aria-pressed="true"] yt-icon * {
    fill: #0099ff !important;
    stroke: none !important;
  }
  #segmented-dislike-button button[aria-pressed="true"] yt-icon {
    fill: #006bb2 !important;
  }
  @keyframes Logo {
    0% {
      transform: scalex(0);
    }
    25% {
      transform: scaleY(0.1);
    }
    50% {
      transform: scalex(0.7);
    }
    75% {
      transform: scaleY(0.15);
    }
  }
  .ytd-topbar-logo-renderer,
  yt-img-shadow.ytd-channel-avatar-editor,
  yt-img-shadow.ytd-topbar-menu-button-renderer,
  #avatar.ytd-rich-grid-media,
  #avatar.ytd-c4-tabbed-header-renderer,
  ytd-video-owner-renderer[modern-metapanel]
    #avatar.ytd-video-owner-renderer,
  yt-img-shadow#avatar.ytd-notification-renderer,
  #avatar.ytd-active-account-header-renderer,
  .yt-spec-button-shape-next--mono.yt-spec-button-shape-next--filled,
  #avatar > yt-img-shadow,
  .image-wrapper.ytd-hero-playlist-thumbnail-renderer,
  button.yt-icon-button,
  .ytSpecButtonShapeNextMono.ytSpecButtonShapeNextTonal,
  .ytSpecAvatarShapeTappable {
    animation-name: Logo;
    animation-duration: 0.8s;
  }
  .ytd-topbar-logo-renderer:hover,
  yt-img-shadow.ytd-channel-avatar-editor:hover,
  yt-img-shadow.ytd-topbar-menu-button-renderer:hover,
  #avatar.ytd-rich-grid-media:hover,
  #avatar.ytd-c4-tabbed-header-renderer:hover,
  ytd-video-owner-renderer[modern-metapanel]
    #avatar.ytd-video-owner-renderer:hover,
  yt-img-shadow#avatar.ytd-notification-renderer:hover,
  #avatar.ytd-active-account-header-renderer:hover,
  .yt-spec-button-shape-next--mono.yt-spec-button-shape-next--filled:hover,
  #avatar > yt-img-shadow:hover,
  .image-wrapper.ytd-hero-playlist-thumbnail-renderer:hover,
  button.yt-icon-button:hover,
  .ytSpecButtonShapeNextMono.ytSpecButtonShapeNextTonal:hover,
  .ytSpecAvatarShapeTappable:hover {
    animation-name: rubberBand;
    animation-duration: 1s;
    animation-delay: 3s;
  }
  @keyframes Scroll {
    30%,
    90% {
      -webkit-transform: translate(calc(0% + 0px), 0);
      transform: translate(calc(0% + 0px), 0);
    }
    80%,
    90% {
      -webkit-transform: translate(calc(-100% + 220px), 0);
      transform: translate(calc(-100% + 200px), 0);
    }
    100% {
      -webkit-transform: translate(calc(0% + 0px), 0);
      transform: translate(calc(0% + 0px), 0);
    }
  }
  #manage-account > a {
    transform: translateZ(0);
    width: auto;
    max-width: 999px;
    min-width: 230px;
    overflow: visible;
    text-overflow: clip;
    animation: Scroll 3s infinite linear;
  }
  @keyframes Fire {
    0% {
      box-shadow: 5px 5px 50px 10px #00beff;
      border-radius: 50px 0px 50px 0;
      color: #075981;
    }
  }
  button.yt-icon-button:hover,
  #button.ytd-topbar-menu-button-renderer:hover,
  .yt-spec-icon-badge-shape__icon:hover,
  a:hover,
  div#voice-search-button:hover,
  button:not([id="search-btn"]):hover,
  .style-scope.ytd-popup-container:hover,
  #guide-wrapper.ytd-app:hover,
  #text.yt-chip-cloud-chip-renderer:hover,
  #endpoint.yt-simple-endpoint.ytd-guide-entry-renderer:hover,
  tp-yt-paper-item.ytd-compact-link-renderer:hover,
  ytd-menu-service-item-renderer:hover,
  .ytLockupViewModelHost:hover,
  ytd-comment-thread-renderer:hover,
  .ytTabShapeHostClickable:hover {
    color: #0099ff;
    text-shadow: 0.5px 0.5px #fff !important;
    animation: Fire 1s ease-in-out;
  }
  @keyframes Backfire {
    0% {
      box-shadow: inset 0 0px 10px 10px #0099ff;
    }
  }
  ytd-searchbox[has-focus] #container.ytd-searchbox,
  [aria-selected="true"],
  ytd-notification-renderer,
  a.ytd-mini-guide-entry-renderer,
  ytd-menu-service-item-renderer[is-selected],
  ytd-macro-markers-list-item-renderer.ytd-horizontal-card-list-renderer,
  .yt-tab-shape-wiz:hover {
    border-radius: 50px 0px 50px 0;
    border: ridge 5px #006bb2;
    animation: Backfire;
    animation-iteration-count: 1;
    animation-duration: 2s;
  }
  @keyframes Background {
    0% {
      background-color: #075981;
    }
    50% {
      background-color: #00ffff;
    }
    100% {
      background-color: #075981;
    }
  }
  .ytp-menuitem[aria-checked="true"] .ytp-menuitem-toggle-checkbox,
  .ytp-settings-button.ytp-hd-quality-badge:after,
  a.ytp-sb-subscribe,
  .yt-spec-icon-badge-shape--style-overlay
    .yt-spec-icon-badge-shape__badge,
  ytd-guide-entry-renderer[line-end-style="dot"]
    #newness-dot.ytd-guide-entry-renderer,
  ytd-notification-renderer.unread #new.ytd-notification-renderer,
  .yt-spec-icon-badge-shape--type-notification
    .yt-spec-icon-badge-shape__badge {
    animation: Background var(--color-transition-duration) linear
      infinite;
  }
  @keyframes Color {
    0% {
      color: #075981;
    }
    50% {
      color: #00ffff;
    }
    100% {
      color: #075981;
    }
  }
  ytd-guide-entry-renderer[active]
    .guide-icon.ytd-guide-entry-renderer,
  sup.ytp-swatch-color,
  .emoji-mart-anchor,
  .badge.ytd-badge-supported-renderer,
  #endpoint
    > tp-yt-paper-item
    > yt-icon.guide-entry-badge.style-scope.ytd-guide-entry-renderer
    > svg,
  yt-icon.ytd-badge-supported-renderer,
  .segment-timestamp.ytd-transcript-segment-renderer {
    animation: Color var(--color-transition-duration) linear infinite;
  }
  @keyframes Border {
    0% {
      border-color: #006bb2;
    }
    50% {
      border-color: #0000;
    }
    100% {
      border-color: #006bb2;
    }
  }
  ytd-thumbnail-overlay-time-status-renderer,
  yt-button-shape.ytd-subscribe-button-renderer,
  #channel-header.ytd-c4-tabbed-header-renderer,
  #container.style-scope.ytd-video-secondary-info-renderer,
  #buttons > ytd-toggle-button-renderer > yt-button-shape > button,
  #header.ytd-app,
  #header.ytd-multi-page-menu-renderer,
  .yt-spec-button-shape-next--call-to-action.yt-spec-button-shape-next--filled,
  #channel-header-container.ytd-topic-channel-details-renderer,
  ytd-channel-video-player-renderer[rounded]
    #player.ytd-channel-video-player-renderer,
  ytd-notification-renderer[rounded-thumbnails]
    .thumbnail-container.ytd-notification-renderer,
  #container.ytd-searchbox,
  .ytSearchboxComponentInputBox {
    animation: Border var(--color-transition-duration) linear infinite;
  }
}

